275|  &state_prefixRoundTrip,
276|  &state_extDictRoundTrip,
277|  &state_loadDictRoundTrip,
278|  &state_attachDictRoundTrip,
279|  &state_prefixHCRoundTrip,
280|  &state_extDictHCRoundTrip,
