64|FUZZ_STATIC uint32_t FUZZ_seed(uint8_t const **src, size_t* size) {
65|    uint8_t const *data = *src;
66|    size_t const toHash = MIN(FUZZ_RNG_SEED_SIZE, *size);
67|    *size -= toHash;
68|    *src += toHash;
69|    return XXH32(data, toHash, 0);
70|}

